#include "database.hpp"
#include <sstream>
namespace ps {
Database::Database(const Settings& s,bool create){conn=mysql_init(nullptr);if(!conn)throw std::runtime_error("MySQL initialization failed");unsigned timeout=8;mysql_options(conn,MYSQL_OPT_CONNECT_TIMEOUT,&timeout);mysql_options(conn,MYSQL_SET_CHARSET_NAME,"utf8mb4");if(!mysql_real_connect(conn,s.host.c_str(),s.user.c_str(),s.password.c_str(),s.database.c_str(),s.port,nullptr,0)){std::string e=mysql_error(conn);mysql_close(conn);conn=nullptr;throw std::runtime_error("MySQL: "+e);}if(create)schema();}
Database::~Database(){if(conn)mysql_close(conn);}
void Database::exec(const std::string& s){if(mysql_real_query(conn,s.c_str(),static_cast<unsigned long>(s.size())))throw std::runtime_error(std::string("Database query failed: ")+mysql_error(conn));MYSQL_RES* r=mysql_store_result(conn);if(r)mysql_free_result(r);}
auto Database::query(const std::string& s)->std::vector<std::vector<std::optional<std::string>>>{if(mysql_real_query(conn,s.c_str(),static_cast<unsigned long>(s.size())))throw std::runtime_error(std::string("Database query failed: ")+mysql_error(conn));MYSQL_RES* r=mysql_store_result(conn);std::vector<std::vector<std::optional<std::string>>> out;if(!r)return out;unsigned cols=mysql_num_fields(r);while(auto row=mysql_fetch_row(r)){auto len=mysql_fetch_lengths(r);std::vector<std::optional<std::string>> item;for(unsigned i=0;i<cols;++i)item.push_back(row[i]?std::optional<std::string>(std::string(row[i],len[i])):std::nullopt);out.push_back(std::move(item));}mysql_free_result(r);return out;}
std::string Database::quote(const std::string& s){std::string out(s.size()*2+3,0);out[0]='\'';auto n=mysql_real_escape_string(conn,out.data()+1,s.data(),static_cast<unsigned long>(s.size()));out[n+1]='\'';out.resize(n+2);return out;}
uint64_t Database::insertId()const{return mysql_insert_id(conn);}
void Database::schema(){
const char* statements[]={
R"(CREATE TABLE IF NOT EXISTS league(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider TINYINT UNSIGNED NOT NULL,external_key VARCHAR(40) NOT NULL,name VARCHAR(120) NOT NULL,country VARCHAR(80) NOT NULL,UNIQUE KEY uq_provider(provider,external_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4)",
R"(CREATE TABLE IF NOT EXISTS team(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider TINYINT UNSIGNED NOT NULL,external_key VARCHAR(160) NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY uq_provider(provider,external_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4)",
R"(CREATE TABLE IF NOT EXISTS fixture(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,league_id INT UNSIGNED NOT NULL,provider TINYINT UNSIGNED NOT NULL,external_id BIGINT UNSIGNED NULL,date DATE NOT NULL,season SMALLINT UNSIGNED NOT NULL,home_id INT UNSIGNED NOT NULL,away_id INT UNSIGNED NOT NULL,status VARCHAR(8) NOT NULL,gh TINYINT UNSIGNED NULL,ga TINYINT UNSIGNED NULL,ch TINYINT UNSIGNED NULL,ca TINYINT UNSIGNED NULL,yh TINYINT UNSIGNED NULL,ya TINYINT UNSIGNED NULL,rh TINYINT UNSIGNED NULL,ra TINYINT UNSIGNED NULL,detail_flags TINYINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_match(league_id,date,home_id,away_id),UNIQUE KEY uq_external(provider,external_id),KEY ix_league_date(league_id,date),KEY ix_home_date(home_id,date),KEY ix_away_date(away_id,date),FOREIGN KEY(league_id) REFERENCES league(id),FOREIGN KEY(home_id) REFERENCES team(id),FOREIGN KEY(away_id) REFERENCES team(id)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC)",
R"(CREATE TABLE IF NOT EXISTS player(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider TINYINT UNSIGNED NOT NULL,external_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY uq_player(provider,external_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4)",
R"(CREATE TABLE IF NOT EXISTS appearance(fixture_id BIGINT UNSIGNED NOT NULL,team_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NOT NULL,starter BOOLEAN NULL,position VARCHAR(8) NULL,shirt SMALLINT UNSIGNED NULL,minutes TINYINT UNSIGNED NULL,goals TINYINT UNSIGNED NULL,assists TINYINT UNSIGNED NULL,shots TINYINT UNSIGNED NULL,shots_on TINYINT UNSIGNED NULL,passes SMALLINT UNSIGNED NULL,tackles TINYINT UNSIGNED NULL,yellow TINYINT UNSIGNED NULL,red TINYINT UNSIGNED NULL,rating DECIMAL(3,1) NULL,PRIMARY KEY(fixture_id,player_id),KEY ix_player(player_id,fixture_id),KEY ix_team(team_id,fixture_id),FOREIGN KEY(fixture_id) REFERENCES fixture(id),FOREIGN KEY(player_id) REFERENCES player(id),FOREIGN KEY(team_id) REFERENCES team(id)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC)",
R"(CREATE TABLE IF NOT EXISTS match_event(fixture_id BIGINT UNSIGNED NOT NULL,seq SMALLINT UNSIGNED NOT NULL,team_id INT UNSIGNED NULL,player_id INT UNSIGNED NULL,minute SMALLINT UNSIGNED NULL,extra TINYINT UNSIGNED NULL,type VARCHAR(24) NOT NULL,detail VARCHAR(80) NOT NULL,PRIMARY KEY(fixture_id,seq),FOREIGN KEY(fixture_id) REFERENCES fixture(id),FOREIGN KEY(player_id) REFERENCES player(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC)",
R"(CREATE TABLE IF NOT EXISTS news(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,team_id INT UNSIGNED NOT NULL,url_hash BINARY(32) NOT NULL,title VARCHAR(512) NOT NULL,url TEXT NOT NULL,published VARCHAR(64) NOT NULL,category VARCHAR(32) NOT NULL,expires DATE NOT NULL,reviewed BOOLEAN NOT NULL DEFAULT 0,goals_for DECIMAL(5,2) NOT NULL DEFAULT 0,goals_against DECIMAL(5,2) NOT NULL DEFAULT 0,corners_for DECIMAL(5,2) NOT NULL DEFAULT 0,corners_against DECIMAL(5,2) NOT NULL DEFAULT 0,cards DECIMAL(5,2) NOT NULL DEFAULT 0,UNIQUE KEY uq_news(team_id,url_hash),KEY ix_team_expiry(team_id,expires),FOREIGN KEY(team_id) REFERENCES team(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC)",
R"(CREATE TABLE IF NOT EXISTS import_state(source_key VARCHAR(180) PRIMARY KEY,content_hash BINARY(32) NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,row_count INT UNSIGNED DEFAULT 0,note VARCHAR(255) DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4)",
R"(CREATE TABLE IF NOT EXISTS injury(fixture_id BIGINT UNSIGNED NOT NULL,player_id INT UNSIGNED NOT NULL,team_id INT UNSIGNED NOT NULL,reason VARCHAR(180) NOT NULL,type VARCHAR(80) NOT NULL,PRIMARY KEY(fixture_id,player_id),FOREIGN KEY(fixture_id) REFERENCES fixture(id),FOREIGN KEY(player_id) REFERENCES player(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4)",
R"(CREATE TABLE IF NOT EXISTS provider_fixture_link(provider TINYINT UNSIGNED NOT NULL,external_id BIGINT UNSIGNED NOT NULL,fixture_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(provider,external_id),UNIQUE KEY uq_fixture_provider(fixture_id,provider),FOREIGN KEY(fixture_id) REFERENCES fixture(id)) ENGINE=InnoDB)",
R"(CREATE TABLE IF NOT EXISTS statistic_type(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB)",
R"(CREATE TABLE IF NOT EXISTS appearance_stat(fixture_id BIGINT UNSIGNED NOT NULL,player_id INT UNSIGNED NOT NULL,statistic_id SMALLINT UNSIGNED NOT NULL,value DECIMAL(12,3) NOT NULL,PRIMARY KEY(fixture_id,player_id,statistic_id),FOREIGN KEY(fixture_id) REFERENCES fixture(id),FOREIGN KEY(player_id) REFERENCES player(id),FOREIGN KEY(statistic_id) REFERENCES statistic_type(id)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC)",
R"(CREATE TABLE IF NOT EXISTS team_match_extra(fixture_id BIGINT UNSIGNED NOT NULL,team_id INT UNSIGNED NOT NULL,shots SMALLINT UNSIGNED NULL,shots_on SMALLINT UNSIGNED NULL,possession DECIMAL(5,2) NULL,xg DECIMAL(6,3) NULL,fouls SMALLINT UNSIGNED NULL,offsides SMALLINT UNSIGNED NULL,saves SMALLINT UNSIGNED NULL,passes SMALLINT UNSIGNED NULL,PRIMARY KEY(fixture_id,team_id),FOREIGN KEY(fixture_id) REFERENCES fixture(id)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC)"
};for(auto* s:statements)exec(s);
    const std::pair<const char*,const char*> columns[]={
      {"appearance.minutes_source","TINYINT UNSIGNED NOT NULL DEFAULT 0"},
      {"appearance.studio_rating","DECIMAL(3,1) NULL"},
      {"news.selected","BOOLEAN NOT NULL DEFAULT 0"},
      {"news.decision","TINYINT NOT NULL DEFAULT 0"},
      {"news.reason","VARCHAR(240) NOT NULL DEFAULT ''"},
      {"news.shots_for","DECIMAL(5,2) NOT NULL DEFAULT 0"},
      {"news.shots_against","DECIMAL(5,2) NOT NULL DEFAULT 0"}};
    for(auto [name,type]:columns){std::string full=name;auto dot=full.find('.');auto table=full.substr(0,dot),column=full.substr(dot+1);
      if(query("SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name="+quote(table)+" AND column_name="+quote(column)).empty()){
        exec("ALTER TABLE "+table+" ADD COLUMN "+column+" "+type);
        if(full=="news.decision")exec("UPDATE news SET decision=1,selected=1 WHERE reviewed=1");
      }
    }
}
int Database::league(int p,const std::string& k,const std::string& n,const std::string& c){exec("INSERT INTO league(provider,external_key,name,country) VALUES("+std::to_string(p)+","+quote(k)+","+quote(n)+","+quote(c)+") ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),name=VALUES(name),country=VALUES(country)");return int(insertId());}
int Database::team(int p,const std::string& k,const std::string& n){exec("INSERT INTO team(provider,external_key,name) VALUES("+std::to_string(p)+","+quote(k)+","+quote(n)+") ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),name=VALUES(name)");return int(insertId());}
static std::string num(int n){return n<0?"NULL":std::to_string(n);}
long long Database::upsertMatch(const Match& m,int provider){std::ostringstream s;s<<"INSERT INTO fixture(league_id,provider,external_id,date,season,home_id,away_id,status,gh,ga,ch,ca,yh,ya,rh,ra) VALUES("<<m.league<<","<<provider<<","<<(m.external?std::to_string(m.external):"NULL")<<","<<quote(m.date)<<","<<m.season<<","<<m.home<<","<<m.away<<","<<quote(m.status);for(int k=0;k<4;++k)s<<","<<num(m.h[k])<<","<<num(m.a[k]);s<<") ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),date=VALUES(date),status=VALUES(status),gh=VALUES(gh),ga=VALUES(ga),ch=COALESCE(VALUES(ch),ch),ca=COALESCE(VALUES(ca),ca),yh=COALESCE(VALUES(yh),yh),ya=COALESCE(VALUES(ya),ya),rh=COALESCE(VALUES(rh),rh),ra=COALESCE(VALUES(ra),ra)";exec(s.str());auto id=insertId();
    for(bool home:{true,false}){int shots=home?m.h[4]:m.a[4];if(shots>=0)exec("INSERT INTO team_match_extra(fixture_id,team_id,shots_on) VALUES("+std::to_string(id)+","+std::to_string(home?m.home:m.away)+","+std::to_string(shots)+") ON DUPLICATE KEY UPDATE shots_on=VALUES(shots_on)");}
    return id;}
std::vector<League> Database::leagues(){std::vector<League> out;for(auto&r:query("SELECT id,external_key,name,country,provider FROM league ORDER BY country,name"))out.push_back({std::stoi(*r[0]),*r[1],*r[2],*r[3],std::stoi(*r[4])});return out;}
std::vector<Team> Database::teams(int league){std::string id=std::to_string(league);std::vector<Team> out;for(auto&r:query("SELECT DISTINCT t.id,t.name FROM team t JOIN (SELECT home_id AS id FROM fixture WHERE league_id="+id+" UNION SELECT away_id AS id FROM fixture WHERE league_id="+id+") f ON t.id=f.id ORDER BY t.name"))out.push_back({std::stoi(*r[0]),*r[1]});return out;}
std::vector<Match> Database::matches(int league,bool future){std::vector<Match> out;std::string sql="SELECT f.id,league_id,date,season,home_id,away_id,status,gh,ga,ch,ca,yh,ya,rh,ra,h.name,a.name,COALESCE(external_id,0),detail_flags,CASE WHEN status='FT' THEN eh.shots_on ELSE NULL END,CASE WHEN status='FT' THEN ea.shots_on ELSE NULL END FROM fixture f JOIN team h ON f.home_id=h.id JOIN team a ON f.away_id=a.id LEFT JOIN team_match_extra eh ON eh.fixture_id=f.id AND eh.team_id=f.home_id LEFT JOIN team_match_extra ea ON ea.fixture_id=f.id AND ea.team_id=f.away_id WHERE league_id="+std::to_string(league)+" AND date>="+quote(future?today():yearsAgo(5))+" ORDER BY date";for(auto&r:query(sql)){Match m;m.id=std::stoll(*r[0]);m.league=std::stoi(*r[1]);m.date=*r[2];m.season=std::stoi(*r[3]);m.home=std::stoi(*r[4]);m.away=std::stoi(*r[5]);m.status=*r[6];for(int k=0;k<4;++k){m.h[k]=r[7+2*k]?std::stoi(*r[7+2*k]):-1;m.a[k]=r[8+2*k]?std::stoi(*r[8+2*k]):-1;}m.homeName=*r[15];m.awayName=*r[16];m.external=std::stoll(*r[17]);m.details=std::stoi(*r[18]);m.h[4]=r[19]?std::stoi(*r[19]):-1;m.a[4]=r[20]?std::stoi(*r[20]):-1;out.push_back(m);}return out;}
std::vector<News> Database::news(int team){std::vector<News> out;std::string q="SELECT id,team_id,title,url,published,category,expires,reviewed,goals_for,goals_against,corners_for,corners_against,cards,selected,decision,reason,shots_for,shots_against FROM news WHERE expires>="+quote(today());if(team)q+=" AND team_id="+std::to_string(team);q+=" ORDER BY id DESC LIMIT 500";for(auto&r:query(q)){News n;n.id=std::stoll(*r[0]);n.team=std::stoi(*r[1]);n.title=*r[2];n.url=*r[3];n.published=*r[4];n.category=*r[5];n.expires=*r[6];n.reviewed=*r[7]=="1";n.goalsFor=std::stof(*r[8]);n.goalsAgainst=std::stof(*r[9]);n.cornersFor=std::stof(*r[10]);n.cornersAgainst=std::stof(*r[11]);n.cards=std::stof(*r[12]);n.selected=*r[13]=="1";n.decision=std::stoi(*r[14]);n.reason=*r[15];n.shotsFor=std::stof(*r[16]);n.shotsAgainst=std::stof(*r[17]);out.push_back(n);}return out;}
void Database::saveNews(const News& n){
    auto effects=",selected="+std::to_string(n.selected)+",decision="+std::to_string(n.decision)+",reason="+quote(n.reason.substr(0,240))+",shots_for="+std::to_string(n.shotsFor)+",shots_against="+std::to_string(n.shotsAgainst);
    if(n.id){exec("UPDATE news SET reviewed="+std::to_string(n.reviewed)+",goals_for="+std::to_string(n.goalsFor)+",goals_against="+std::to_string(n.goalsAgainst)+",corners_for="+std::to_string(n.cornersFor)+",corners_against="+std::to_string(n.cornersAgainst)+",cards="+std::to_string(n.cards)+",expires="+quote(n.expires)+effects+" WHERE id="+std::to_string(n.id));return;}
    exec("INSERT INTO news(team_id,url_hash,title,url,published,category,expires,selected,decision,reason,goals_for,goals_against,corners_for,corners_against,cards,shots_for,shots_against,reviewed) VALUES("+std::to_string(n.team)+",UNHEX(SHA2("+quote(n.url)+",256)),"+quote(n.title.substr(0,500))+","+quote(n.url)+","+quote(n.published.substr(0,60))+","+quote(n.category)+","+quote(n.expires)+","+std::to_string(n.selected)+","+std::to_string(n.decision)+","+quote(n.reason.substr(0,240))+","+std::to_string(n.goalsFor)+","+std::to_string(n.goalsAgainst)+","+std::to_string(n.cornersFor)+","+std::to_string(n.cornersAgainst)+","+std::to_string(n.cards)+","+std::to_string(n.shotsFor)+","+std::to_string(n.shotsAgainst)+","+std::to_string(n.reviewed)+") ON DUPLICATE KEY UPDATE title=VALUES(title)");
}
}
